module agent_generic_module(input logic clk,rst_n,input logic [47:0] in_a,in_data,input logic [2:0] in_b,output logic [47:0] out_word,out_old_word);logic [47:0] t;always_comb begin t=in_a;t[23-:12]=in_data[11:0];t[15:0]=t[31:16]; end always_ff @(posedge clk or negedge rst_n)if(!rst_n)begin out_word<=48'd0;out_old_word<=48'd0;end else begin out_old_word<=out_word;if(in_b)out_word<=t;end endmodule
